<?php
require_once __DIR__.'/config.php'; require_once __DIR__.'/includes/policy-system.php'; requireLogin();
$u=currentUser(); if($u['role']==='employee'){http_response_code(403);exit('Owner or administrator access is required.');}
$db=db(); hrPolicyEnsureSchema($db); $v=hrPolicyVersion($db,(int)($_GET['id']??0)); if(!$v){http_response_code(404);exit('Version not found.');}
$s=$db->prepare("SELECT e.id,e.emp_number,TRIM(CONCAT(e.first_name,' ',e.last_name)) employee_name,a.id ack_id,a.opened_at,a.last_opened_at,a.reading_percent,a.reached_end_at,a.signed_at,pn.created_at notification_sent_at,pn.delivered_at notification_delivered_at,pn.opened_at notification_opened_at FROM employees e LEFT JOIN users u ON u.employee_id=e.id AND u.role='employee' LEFT JOIN hr_policy_acknowledgements a ON a.employee_id=e.id AND a.version_id=? LEFT JOIN hr_policy_notifications pn ON pn.user_id=u.id AND pn.version_id=? WHERE e.status='active' ORDER BY e.first_name,e.last_name");
$s->execute(array($v['id'],$v['id'])); $rows=$s->fetchAll(PDO::FETCH_ASSOC); $signed=0;$opened=0;$overdue=0;
foreach($rows as $r){if($r['signed_at'])$signed++;elseif($r['opened_at'])$opened++;if(!$r['signed_at']&&$v['acknowledgement_deadline']&&date('Y-m-d')>$v['acknowledgement_deadline'])$overdue++;}$required=count($rows);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Policy acknowledgements</title><link rel="stylesheet" href="includes/styles.css"><link rel="stylesheet" href="includes/policies.css"></head><body class="policy-shell"><?php include __DIR__.'/includes/sidebar.php';?><main class="policy-main"><a href="policies.php" class="back-link">← Documents & Policies</a><header class="policy-page-head"><div><span class="eyebrow">Acknowledgements · Version <?=htmlspecialchars($v['version_number'])?></span><h1><?=htmlspecialchars($v['title'])?></h1><p>Active employee acknowledgement status and reading progress.</p></div></header><div class="summary-grid"><div><span>Employees required</span><b><?=$required?></b></div><div><span>Signed</span><b><?=$signed?></b></div><div><span>Pending</span><b><?=$required-$signed?></b></div><div><span>Not opened</span><b><?=$required-$signed-$opened?></b></div><div><span>Overdue</span><b><?=$overdue?></b></div><div><span>Acknowledgement rate</span><b><?=$required?number_format($signed/$required*100,1):'0.0'?>%</b></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Version</th><th>Opened</th><th>Progress</th><th>Last opened</th><th>Signed</th><th>Signed date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$status=hrPolicyAckStatus($v,$r);?><tr><td><?=htmlspecialchars($r['employee_name'])?><small><?=htmlspecialchars($r['emp_number']?:'Employee '.$r['id'])?></small></td><td><?=htmlspecialchars($v['version_number'])?></td><td><?=$r['opened_at']?'Yes':'No'?></td><td><?=number_format((float)($r['reading_percent']??0),0)?>%<?=$r['reached_end_at']?' · acknowledgement reached':''?></td><td><?=$r['last_opened_at']?date('j M Y H:i',strtotime($r['last_opened_at'])):'—'?></td><td><?=$r['signed_at']?'Yes':'No'?></td><td><?=$r['signed_at']?date('j M Y H:i',strtotime($r['signed_at'])):'—'?></td><td><span class="status-pill"><?=htmlspecialchars($status)?></span></td><td><?=$r['ack_id']&&$r['signed_at']?'<a href="policy-receipt.php?id='.(int)$r['ack_id'].'">View</a>':''?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>
